SELECT COUNT(DISTINCT f.findistref) FROM operations o
JOIN financials f ON o.opsregistry = f.fin_ops_ref
WHERE o.emerglevel = 'Red';

-- Check all columns in all tables for anything related to PHRS or health risk
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%health%' OR column_name LIKE '%risk%' OR column_name LIKE '%phr%';

SELECT COUNT(*) FROM disasterevents 
WHERE haz_level = 'Severity-5' 
AND COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) > 0;

-- Maybe the criteria is just casualties > 100 (not including injured)
SELECT COUNT(*) FROM disasterevents 
WHERE COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) > 100;

SELECT COUNT(*) FROM disasterevents 
WHERE COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) + COALESCE((impact_summary->'population_impact'->>'injured')::int, 0) > 100
AND (impact_summary->'population_impact'->>'injured') IS NOT NULL;

-- Check what count we get for Red emerglevel through financials
SELECT COUNT(DISTINCT findistref) FROM financials WHERE fin_ops_ref IN (
    SELECT opsregistry FROM operations WHERE emerglevel = 'Red'
);

SELECT COUNT(*) FROM disasterevents 
WHERE haz_level = 'Severity-5' AND haztype = 'Earthquake'
AND COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) + COALESCE((impact_summary->'population_impact'->>'injured')::int, 0) > 100;

-- Check if missing > 100 gives 54
SELECT COUNT(*) FROM disasterevents 
WHERE COALESCE((impact_summary->'population_impact'->>'missing')::int, 0) > 100;

-- Check affected > 100000
SELECT COUNT(*) FROM disasterevents 
WHERE COALESCE((impact_summary->'population_impact'->>'affected')::int, 0) > 100000;

-- Check how many disasters have humanresources records with medical < some threshold
SELECT COUNT(DISTINCT h.hrdistref) FROM humanresources h 
WHERE COALESCE((h.staffing_details->'staff_counts'->>'medical')::int, 0) < 20;

-- Check how many disasters have humanresources records with medical < 50
SELECT COUNT(DISTINCT h.hrdistref) FROM humanresources h 
WHERE COALESCE((h.staffing_details->'staff_counts'->>'medical')::int, 0) < 50;

-- Check disasters with infra_damage_pct > 80
SELECT COUNT(*) FROM disasterevents 
WHERE (impact_summary->'infrastructure_damage'->>'infra_damage_pct')::int > 80;

-- Check disasters with infra_damage_pct > 80 (cast as numeric)
SELECT COUNT(*) FROM disasterevents 
WHERE CAST(impact_summary->'infrastructure_damage'->>'infra_damage_pct' AS numeric) > 80;

SELECT COUNT(*) FROM disasterevents 
WHERE haz_type IN ('Earthquake', 'Tsunami') AND haz_level = 'Severity-5'
AND COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) + COALESCE((impact_summary->'population_impact'->>'injured')::int, 0) > 100;

SELECT COUNT(*) FROM disasterevents 
WHERE haztype IN ('Earthquake', 'Tsunami') AND haz_level = 'Severity-5'
AND COALESCE((impact_summary->'population_impact'->>'casualties')::int, 0) + COALESCE((impact_summary->'population_impact'->>'injured')::int, 0) > 100;
